function addContactShadows(){
 // Broad, low-opacity contact occlusion complements the physically projected shadow map.
 const size=128,bytes=new Uint8Array(size*size*4);for(let y=0;y<size;y++)for(let x=0;x<size;x++){const dx=(x/(size-1)-.5)*2,dy=(y/(size-1)-.5)*2;const r=Math.pow(dx/1.03,8)+Math.pow(dy,8);const a=Math.max(0,1-r);const k=(y*size+x)*4;bytes[k]=bytes[k+1]=bytes[k+2]=30;bytes[k+3]=Math.round(28*a);}
 const tex=new T.DataTexture(bytes,size,size,T.RGBAFormat);tex.needsUpdate=true;
 const m=new T.MeshBasicMaterial({map:tex,transparent:true,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-2,toneMapped:false});
 const p=plane(wall,.96,.64,m,roomScene?roomScene.walls[0].length/2:0,.55,roomScene ? .009 : -.221);p.name='Occlusion_contact_caisson';p.renderOrder=1;cabinetContact=p;
}

