let photorealProjectReady=false;
const photorealExport=createPhotorealExport({name:'RANDAL STUDIO ONE',filename:'randal-studio-one',capture:()=>captureHD(),getProject:()=>collectProject(),getPrompt:buildStudioPhotorealPrompt});
const captureHD=createHDCapture({
 snapshot(){
  if(!state.ready||!renderer)throw Error('Attendez la fin du chargement du projet.');
  const size=new T.Vector2();renderer.getSize(size);
  const prior={quality:{...quality,samples:[...quality.samples]},ratio:renderer.getPixelRatio(),size,aspect:camera.aspect,controls:controls.enabled,inert:document.body.inert,windows:windowMotionSnapshot(),finishes:{...finishTextures},surfaces:Object.fromEntries(Object.entries(surfaceTextures).map(([name,entries])=>[name,{...entries}]))};
  captureBusy=true;document.body.inert=true;controls.enabled=false;return prior;
 },
 async prepare(previous){
  await windowLoader().ensureItems(composition?.items);await prepareActiveTextures(quality.profile.id);previous.finishes={...finishTextures};previous.surfaces=Object.fromEntries(Object.entries(surfaceTextures).map(([name,entries])=>[name,{...entries}]));quality.textureExporting=true;quality.level=0;quality.pause();
  await prepareActiveTextures('max');applyQuality();syncWindowStates(true);
  if(renderer.compileAsync)await renderer.compileAsync(scene,camera);
 },
 render({width=1920}={}){
  const max=Math.min(renderer.capabilities.maxTextureSize||4096,renderer.capabilities.maxRenderbufferSize||16384),size=captureSize(width,stage.clientWidth/stage.clientHeight,max);
  if(size.width<1920)throw Error('Ce navigateur ne dispose pas de la mémoire nécessaire pour une image HD.');
  renderer.setPixelRatio(1);renderer.setSize(size.width,size.height,false);camera.aspect=size.width/size.height;camera.updateProjectionMatrix();ultraPipeline?.resize(size.width,size.height,1);
  renderer.shadowMap.needsUpdate=true;sceneRevision++;for(const item of composition?.items||[])item.asset.reflector?.userData.reflectionSchedule.reset();
  return withoutEditorGuides(scene,()=>{if(ultraPipeline)ultraPipeline.render(.016);else renderer.render(scene,camera);
  const result=canvas.toDataURL('image/png');lastCapture={...size,profile:'max',textures:textureDiagnostics(),at:Date.now()};return result;});
 },
 restore(previous){
  try{
   Object.assign(quality,previous.quality);quality.textureExporting=false;quality.pause();
   for(const id of Object.keys(finishTextures))delete finishTextures[id];Object.assign(finishTextures,previous.finishes);
   for(const collection of Object.keys(surfaceTextures))delete surfaceTextures[collection];for(const [collection,entries]of Object.entries(previous.surfaces))surfaceTextures[collection]={...entries};
   refreshFurnitureMaterials();applyAllRoomMaterials();applyQuality();restoreWindowMotion(previous.windows);renderer.setPixelRatio(previous.ratio);renderer.setSize(previous.size.x,previous.size.y,false);activePixelRatio=previous.ratio;camera.aspect=previous.aspect;camera.updateProjectionMatrix();ultraPipeline?.resize(previous.size.x,previous.size.y,previous.ratio);pruneTextures(quality.profile.id);
  }finally{controls.enabled=previous.controls;document.body.inert=previous.inert;captureBusy=false;running=false;invalidate(false,false);}
 }
});
