function refreshProfiles(){if(sceneUpdates.defer('profiles',refreshProfiles))return;if(!roomScene)return;if(profileAsset){profileAsset.group.removeFromParent();disposeObject(profileAsset.group);}profileAsset=buildProfiles(roomScene,profileSettings,wallFinishes,composition?.items||[]);roomScene.root.add(profileAsset.group);if(quality.profile.id==='fluid')lightweightMaterials.apply(profileAsset.group,true);$('#profile-enabled').checked=profileSettings.enabled;$('#profile-color').value=profileSettings.color;$('#profile-edit').textContent=profileSettings.editMode?'Terminer les angles':'Modifier les angles au clic';$('#profile-internal').checked=!!profileSettings.internalCorners;$('#profile-selected-wall').checked=profileSettings.walls.includes(selectedWall);$('#profile-summary').textContent=(profileAsset.metres||0).toLocaleString('fr-FR',{maximumFractionDigits:2})+' m · angles externes, rives et baignoires';}
function exportQuantities(){const r=quantityReport();if(r.plinths.error){placementStatus('Corrigez les plinthes avant d’exporter le relevé : '+r.plinths.error);return;}const csv=[[t('Zone'),t('Fabricant'),t('Collection'),t('Couleur'),t('Format'),t('Référence'),t('Surface réelle m²'),t('Besoin m²'),t('Entiers'),t('Découpés'),t('Boîtes'),t('Pièces/boîte'),t('m²/boîte'),t('Surface commandée m²'),...(showPurchasePrices?[t('Achat HT/m²'),t('Total achat HT')]:[])],...r.rows.map(v=>[t(v.label),v.brand||t('Peinture'),v.collection,v.color,v.format||'',v.reference||'',v.area,v.needed||'',v.full??'',v.cut??'',v.boxes??'',v.pcsBox||'',v.m2Box||'',v.orderArea??'',...(showPurchasePrices?[v.purchaseHT??'',Number.isFinite(v.purchaseHT)&&v.orderArea!==null?v.purchaseHT*v.orderArea:'']:[])]),[],[t('Commande groupée')],...r.groups.map(v=>['',v.brand,v.collection,v.color,v.format,v.reference||'',v.area,v.needed,v.full,v.cut,v.boxes,v.pcsBox,v.m2Box,v.orderArea,...(showPurchasePrices?[v.purchaseHT??'',v.totalPurchaseHT??'']:[])]),[],[t('Plinthes'),r.plinths.type,t('Réel ml'),r.plinths.net,t('Débit avec chutes ml'),r.plinths.debit,t('À acheter ml'),r.plinths.order,t('Carreaux / pièces / barres'),r.plinths.units,t('Référence'),r.plinths.product?.reference||'',...(showPurchasePrices?[t('Unité du prix'),r.plinthsCost.unit,t('Achat HT/unité'),r.plinthsCost.unitPriceHT,t('Montant achat HT'),r.plinthsCost.totalHT,r.plinthsCost.included?t('Déjà inclus dans le carrelage commandé'):t('En supplément du carrelage')]:[]) ],[],[t('Profilés aluminium (m)'),r.profiles]].map(row=>row.map(v=>JSON.stringify(v==null?'':typeof v==='number'?Math.round(v*100)/100:v)).join(';')).join('\r\n');downloadFile(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),'surfaces-calepinage-plinthes.csv');}


function initializeWorkspace(){
 projectWorkspace=createWorkspace({readonly:()=>!!publicCompositionSession?.isPreview,onPublicCompositions:()=>publicCompositionGallery?.show(),getProject:()=>state.ready?collectProject():null,onDeletedActive:()=>{location.href=demoRoute('index.html?new=1');},onUpdate:data=>{markStudioEntryEdited(localStorage);$('#project-title').value=data.title;state.siteReference=data.siteReference||'';},onOpen:(data,id,record)=>{publicCompositionSession?.leave({restore:false});markStudioEntryEdited(localStorage);if(record?.kind==='house'){location.href=demoRoute('maison.html?project='+encodeURIComponent(id));return;}if(!restoreProject(data))throw Error('Ce projet ne peut pas être ouvert.');journal.seed(collectProject());updateHistoryButtons();},
 onLock:(locked)=>{for(const selector of ['#settings','#object-editor','#add-menu']){const el=$(selector);if(el)el.inert=locked;}for(const id of ['project-title','undo','redo','save-project','add-open']){const el=$('#'+id);if(el)el.disabled=locked;}if(locked){productDragController?.cancel();dragController?.cancel();partitionDragController?.cancel();productDragController?.cancel();closeElementPanel();closeInspector();}},status:placementStatus,
 getThumbnail:()=>captureBusy?null:captureImage(320,true)});
 const send=$('#share-project');send.hidden=true;
 const footer=document.createElement('section');footer.className='setting-section';footer.innerHTML='<button type="button" class="lrf-admin-send" id="send-project-administrator">Envoyer le projet à l’administrateur</button><button type="button" class="room-secondary" id="duplicate-active-project">Dupliquer le projet</button>';
 $('#settings').append(footer);footer.querySelector('#send-project-administrator').onclick=async e=>{const b=e.currentTarget;b.disabled=true;b.textContent='Préparation du projet…';try{await projectWorkspace.sendAdministrator();}catch(error){placementStatus(error.message);}finally{b.disabled=false;b.textContent='Envoyer le projet à l’administrateur';}};footer.querySelector('#duplicate-active-project').onclick=()=>publicCompositionSession?.isPreview?copyPublicComposition(publicCompositionSession.composition.id):projectWorkspace.duplicate();
 // Keep camera navigation available while validated project data is immutable.
 document.addEventListener('keydown',e=>{if(projectWorkspace.locked&&(e.key==='Delete'||e.key==='Backspace'||(e.ctrlKey||e.metaKey)&&['z','y'].includes(e.key.toLowerCase()))){e.preventDefault();e.stopImmediatePropagation();}},true);
 initializePublicCompositions();
}


function publicCompositionChanged(mode){
 clearTimeout(projectTimer);projectTimer=null;journal?.seed(collectProject());updateHistoryButtons();publicCompositionBanner?.refresh();
 if(mode!=='close'){setView('room',true);closeInspector();}
 if(mode==='copy'){placementStatus('Votre copie est prête : vous pouvez modifier et enregistrer ce projet.');}
}
function previewPublicComposition(id,options){return publicCompositionSession.preview(id,options);}
function copyPublicComposition(id,options){return publicCompositionSession.copy(id,options);}
function initializePublicCompositions(){
 publicCompositionSession=createPublicCompositionSession({getProject:collectProject,restoreProject,getWorkspace:()=>projectWorkspace,storage:localStorage,activeKey:ACTIVE_ID,onBefore:()=>{walkMode?.setActive(false);clearTimeout(projectTimer);projectTimer=null;},onChange:publicCompositionChanged});
 publicCompositionBanner=mountPublicCompositionBanner({stage,session:publicCompositionSession,onCopy:copyPublicComposition,onVisit:()=>{if(publicCompositionSession.isPreview){projectWorkspace?.refreshLock();walkMode?.setActive(true);}}});
 publicCompositionGallery=mountPublicCompositionsGallery({getCompositions:()=>PUBLIC_COMPOSITIONS,getCurrentVariant:()=>'studio-one',onPreview:composition=>previewPublicComposition(composition.id),onCopy:composition=>copyPublicComposition(composition.id),onNavigate:({composition,mode})=>{navigatePublicComposition(composition,mode);}});
 const params=new URLSearchParams(location.search),id=params.get('composition');if(id){const descriptor=publicComposition(id);if(descriptor?.variant!=='studio-one'){if(descriptor)navigatePublicComposition(descriptor,params.get('compositionMode')||'preview');return;}try{params.get('compositionMode')==='copy'?copyPublicComposition(id,{checkpoint:false}):previewPublicComposition(id,{checkpoint:false});}catch(error){placementStatus(error.message);}}
}

